    'Kabarıklık yok':{en:'No wheals',de:'Keine Quaddeln',fr:'Pas de papules urticariennes',es:'Sin habones'}, 'Kaşıntı yok':{en:'No itch',de:'Kein Juckreiz',fr:'Pas de prurit',es:'Sin prurito'}, 'Hafif':{en:'Mild',de:'Leicht',fr:'Léger',es:'Leve'}, 'Orta; rahatsız edici, aktivite/uykuyu bozmaz':{en:'Moderate; troublesome but does not interfere with activity/sleep',de:'Mittelgradig; störend, beeinträchtigt Aktivität/Schlaf jedoch nicht',fr:'Modéré ; gênant mais sans perturber l’activité/le sommeil',es:'Moderado; molesto pero no interfiere con la actividad/el sueño'}, 'Şiddetli; aktivite veya uykuyu etkiler':{en:'Severe; interferes with activity or sleep',de:'Schwer; beeinträchtigt Aktivität oder Schlaf',fr:'Sévère ; perturbe l’activité ou le sommeil',es:'Grave; interfiere con la actividad o el sueño'}, 'geniş birleşik alanlar':{en:'large confluent areas',de:'große konfluierende Areale',fr:'larges zones confluentes',es:'grandes áreas confluentes'},

    'Bir kadran':{en:'One quadrant',de:'Ein Quadrant',fr:'Un quadrant',es:'Un cuadrante'}, 'İki kadran':{en:'Two quadrants',de:'Zwei Quadranten',fr:'Deux quadrants',es:'Dos cuadrantes'}, 'Üç kadran':{en:'Three quadrants',de:'Drei Quadranten',fr:'Trois quadrants',es:'Tres cuadrantes'}, 'Tüm saçlı deri':{en:'Entire scalp',de:'Gesamte Kopfhaut',fr:'Tout le cuir chevelu',es:'Todo el cuero cabelludo'},
