    '0 yok · 1 hafif · 2 orta · 3 belirgin':{en:'0 none · 1 mild · 2 moderate · 3 marked',de:'0 keine · 1 leicht · 2 mittel · 3 ausgeprägt',fr:'0 aucune · 1 légère · 2 modérée · 3 marquée',es:'0 ninguna · 1 leve · 2 moderada · 3 marcada'},
    '0 yok · 1 parlak · 2 görünür damarlar · 3 belirgin cliff-drop':{en:'0 none · 1 shiny · 2 visible vessels · 3 marked cliff-drop',de:'0 keine · 1 glänzend · 2 sichtbare Gefäße · 3 ausgeprägter Cliff-drop',fr:'0 aucune · 1 brillante · 2 vaisseaux visibles · 3 cliff-drop marqué',es:'0 ninguna · 1 brillante · 2 vasos visibles · 3 cliff-drop marcado'},
    '0 yok · 1 düz · 2 konkav · 3 belirgin':{en:'0 none · 1 flat · 2 concave · 3 marked',de:'0 keine · 1 flach · 2 konkav · 3 ausgeprägt',fr:'0 aucune · 1 plane · 2 concave · 3 marquée',es:'0 ninguna · 1 plana · 2 cóncava · 3 marcada'},
    '0 yok · 1 hafif · 2 orta · 3 belirgin hiper- veya hipopigmentasyon':{en:'0 none · 1 mild · 2 moderate · 3 marked hyper- or hypopigmentation',de:'0 keine · 1 leicht · 2 mittel · 3 ausgeprägte Hyper- oder Hypopigmentierung',fr:'0 aucune · 1 légère · 2 modérée · 3 hyper- ou hypopigmentation marquée',es:'0 ninguna · 1 leve · 2 moderada · 3 hiper- o hipopigmentación marcada'},
